insert into public.categories (slug, name, tagline, description, image, sort_order) values ('sweaters', 'Sweaters', 'The ones you reach for first', 'Crewnecks, cables, rollnecks and chunky ribs. Cut to be worn for years and to soften with every winter.', 'products/sweater-12.webp', 1);
insert into public.categories (slug, name, tagline, description, image, sort_order) values ('cardigans', 'Cardigans', 'A layer for every room', 'Buttoned, cropped, open and oversized — cardigans to wear over a shirt, a dress or another sweater from October to April.', 'products/cardigan-05.webp', 2);
insert into public.categories (slug, name, tagline, description, image, sort_order) values ('hats', 'Hats', 'Warm ears, all season', 'Ribbed beanies and slouchy knits in the same yarns as our sweaters.', 'products/hat-02.webp', 3);
insert into public.categories (slug, name, tagline, description, image, sort_order) values ('scarves', 'Scarves', 'Wrapped twice, at least', 'Long scarves, airy mohair and wide wraps generous enough to double as a shawl on a cold train platform.', 'products/scarf-03.webp', 4);
insert into public.categories (slug, name, tagline, description, image, sort_order) values ('mittens', 'Mittens', 'Warm hands, bright patterns', 'Patterned mittens in the Latvian tradition — the one piece of knitwear where we let colour run wild.', 'products/mittens-02.webp', 5);
insert into public.categories (slug, name, tagline, description, image, sort_order) values ('socks', 'Socks', 'Made to be worn out', 'Ribbed everyday socks, lace-cable socks and patterned pairs for a cold floor on a winter morning.', 'products/socks-03.webp', 6);
